.range-trigger { display: flex; width: 100%; min-height: 37px; align-items: center; gap: 8px; border: 1px solid #dfe7f1; border-radius: 8px; padding: 8px 10px; color: #3e587b; background: #fff; font: inherit; font-size: 10px; text-align: left; cursor: pointer; }
.range-trigger > svg:first-child { flex: 0 0 auto; color: #2979ed; }
.range-trigger > span { overflow: hidden; flex: 1; text-overflow: ellipsis; white-space: nowrap; }
.range-chevron { flex: 0 0 auto; color: #7b8da7; }
.range-popover { position: absolute; z-index: 90; top: calc(100% + 6px); left: 0; width: min(720px, calc(100vw - 24px)); overflow: hidden; border: 1px solid #dfe7f1; border-radius: 12px; padding: 11px; background: #fff; box-shadow: 0 16px 36px rgb(20 48 86 / 17%); }
.range-presets { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
.range-presets button { border: 1px solid #e5ebf3; border-radius: 7px; padding: 7px 8px; color: #536b8d; background: #f9fbfd; font-size: 9px; text-align: center; cursor: pointer; }
.range-presets button:hover { border-color: #bdd5f7; color: #1769d2; background: #f0f6ff; }
.range-picker-scroll { max-width: 100%; margin-top: 8px; overflow: auto; }
.range-picker-scroll :deep(.v-date-range-picker) { max-width: none; }
.range-error { margin: 8px 0 0; color: #c33d50; font-size: 9px; }
.range-actions { display: flex; justify-content: flex-end; gap: 7px; margin-top: 5px; padding-top: 9px; border-top: 1px solid #edf1f6; }
.range-actions button { border: 1px solid #e0e7f1; border-radius: 7px; padding: 7px 11px; color: #667b99; background: #fff; font-size: 9px; font-weight: 700; cursor: pointer; }
.range-actions .range-clear { margin-right: auto; }
.range-hint { margin-right: auto; color: #93a1b5; font-size: 9px; }
@media (max-width: 700px) {
  .range-popover { position: fixed; top: 66px; right: 8px; bottom: calc(78px + env(safe-area-inset-bottom)); left: 8px; display: flex; width: auto; max-height: none; flex-direction: column; }
  .range-presets { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .range-picker-scroll { flex: 1; }
}
</style>
